"""Publish real museum captures and reproducible regression evidence."""
from pathlib import Path
import hashlib, html, json, shutil

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'doc/book/iterations/2026-10-11-teach-a-sphere-height'
RUN = ROOT / 'ada_run/encounter_pilot/ML_Perception/height_learning'
ART = ROOT / 'commons/artifacts/vogue_timeline'

def main():
    tests = json.loads((OUT / 'tests.json').read_text(encoding='utf-8'))
    museum = json.loads((RUN / 'report.json').read_text(encoding='utf-8'))
    pose_path = ROOT / 'doc/book/iterations/2026-10-11-teach-a-sphere/tests.json'
    dance_path = ROOT / 'doc/book/iterations/2026-10-11-vogue-a-phrase-of-your-own/tests.json'
    pose = json.loads(pose_path.read_text(encoding='utf-8'))
    dance = json.loads(dance_path.read_text(encoding='utf-8'))
    assert tests['passed'] and museum['passed'] and pose['passed'] and not dance['failures']
    log = (RUN / 'stdout.log').read_text(encoding='utf-8', errors='replace')
    assert 'SCRIPT ERROR:' not in log, 'Museum capture has GDScript exceptions'
    for name in ['museum', 'empty', 'low', 'high', 'reverse']:
        shutil.copy2(RUN / f'{name}.png', OUT / f'{name}.png')
    for source, name in [(RUN / 'report.json', 'museum-tests.json'), (pose_path, 'pose-tests.json'), (dance_path, 'dance-tests.json'), (ART / 'HEIGHT.md', 'notes.md')]:
        shutil.copy2(source, OUT / name)
    for name in ['height_learner.gd', 'height_learning.gd', 'pose_learning_station.gd']:
        shutil.copy2(ART / name, OUT / name)
    diagnostics = [s for s in log.splitlines() if s.startswith(('ERROR:', 'WARNING:', 'SCRIPT ERROR:'))]
    (OUT / 'museum-diagnostics.json').write_text(json.dumps(diagnostics, indent=2), encoding='utf-8')
    count, spatial, previous = len(tests['checks']), len(museum['checks']), len(pose['checks']) + len(dance['checks'])
    evidence = tests['evidence']
    code = html.escape((ART / 'height_learner.gd').read_text(encoding='utf-8'))
    content = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teach the sphere an amount · Endless Museum</title><style>
    :root{{color-scheme:dark}}*{{box-sizing:border-box}}body{{margin:0;background:#10131e;color:#f4f1f6;font:18px/1.65 system-ui,sans-serif}}main{{max-width:1200px;margin:auto;padding:48px 26px 90px}}h1{{font-size:clamp(40px,7vw,84px);line-height:1.08;letter-spacing:-.05em;max-width:1000px}}h2{{margin-top:2.3em}}a{{color:#7dd6ff}}.lead{{font-size:24px;max-width:890px}}.kicker{{color:#ffc567;letter-spacing:.1em;text-transform:uppercase;font-size:13px}}figure{{margin:30px 0}}img{{display:block;width:100%;border-radius:8px}}figcaption{{font-size:14px;color:#c0bfd0;margin-top:10px}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:24px}}.card{{padding:24px;background:#1b2031;border:1px solid #373c52;border-radius:10px}}.card h2{{margin-top:0}}table{{border-collapse:collapse;width:100%;font-size:16px}}td,th{{text-align:left;padding:14px;border-bottom:1px solid #3b4158;vertical-align:top}}pre{{font-size:13px;line-height:1.5;overflow:auto;padding:24px;background:#070a12}}.stamp{{display:inline-block;border:1px solid #65727b;padding:8px 14px;border-radius:24px;font-size:14px}}li{{margin:12px 0}}@media(max-width:760px){{.grid{{grid-template-columns:1fr}}main{{padding:26px 16px}}}}</style></head>
    <body><main><p class="kicker">Endless Museum · ML_Perception · 11 October 2026</p><h1>Teach the sphere<br>an amount.</h1><p class="lead">The same sphere now learns a continuous relationship. Choose its desired height, demonstrate with your hands, then let your examples shape the movement.</p><p class="stamp">{count} height checks · {spatial} museum checks · {previous} carried pose and dance checks</p>
    <figure><img src="museum.png" alt="The height learning station beside the dance in the actual Endless Museum"><figcaption>Actual Godot museum capture. The same console switches between POSE and HEIGHT. The visitor session begins empty.</figcaption></figure>
    <div class="grid"><section class="card"><h2>What carries forward</h2><p>Two tracked hands, short deliberate takes, your examples, training, fresh tests and the same sphere. POSE learns which category to choose. HEIGHT learns how much to move.</p><p>The two lessons keep separate datasets and local saves. Switching back does not erase the previous work.</p></section><section class="card"><h2>What is new</h2><p>A slider chooses the desired sphere height. CAPTURE pairs that target with the mean height of both hands relative to your head. A real linear regression model fits slope and offset.</p><p>Cyan dots show your examples; a yellow line shows what the model fitted. A moving white point shows the live prediction.</p></section></div>
    <h2>Try it in the museum</h2><ol><li>At <strong>TEACH A SPHERE</strong>, choose <strong>HEIGHT → TEACH</strong>. Set the slider to a desired sphere height.</li><li>Press <strong>CAPTURE</strong>. Use the three-second countdown to arrange your hands, then hold their height briefly. This records one input-target pair.</li><li>Repeat at least three times at different hand heights. Try low hands / low sphere, middle / middle, high / high.</li><li>Press <strong>TRAIN</strong>. Watch the line fit the dots. Training ends in <strong>TEST</strong>.</li><li>Choose an expected sphere height and capture a fresh hand height between those already taught. Read the error in metres. Testing leaves the learned parameters unchanged.</li><li>Choose <strong>LIVE</strong>. Your hands now drive the same sphere continuously along its rail. Outside the taught range or without tracking, it returns to idle.</li><li>Reset the height session and reverse the examples: <strong>low hands / high sphere; high hands / low sphere</strong>. Train again. The relationship changes because your examples changed.</li></ol>
    <figure><img src="empty.png" alt="Height slider, capture and learning controls on the empty station"><figcaption>The target slider previews the sphere in TEACH and TEST. LIVE uses the learned output. The player can SAVE / LOAD either lesson locally.</figcaption></figure>
    <h2>One learned line, many heights</h2><p>These captures use a labelled synthetic rehearsal fitted inside Godot. It is an actual learned model, but not a demonstration of human recognition accuracy. Its fixture examples are never installed in the visitor session.</p>
    <div class="grid"><figure><img src="low.png" alt="Low intermediate input produces a low sphere height"><figcaption>A new lower input is evaluated between training examples.</figcaption></figure><figure><img src="high.png" alt="Higher intermediate input produces a high sphere height"><figcaption>A higher input moves the same sphere upward. No category switch is needed.</figcaption></figure></div>
    <figure><img src="reverse.png" alt="Reversed training pairs produce a descending fitted line and a lowered sphere"><figcaption>After fitting reversed targets, the same higher hand input lowers the sphere. The line changes direction.</figcaption></figure>
    <h2>The limit is visible too</h2><p>The model sees one number: mean hand height relative to the head. It cannot distinguish two poses that share that measurement. Its straight line cannot fit every curved relationship. In a deliberately curved test, the remaining mean squared error is <strong>{evidence['curved_fixture_mse']:.3f}</strong>.</p><p>This is useful material for the critical track: the visitor chooses what a gesture should do; the software chooses which differences it can measure. Both decisions shape the interaction.</p>
    <h2>Tested as running code</h2><table><thead><tr><th>Question</th><th>Evidence</th></tr></thead><tbody><tr><td>Does it actually fit?</td><td>Both parameters change. Linear-fixture MSE falls from {evidence['loss_before']:.3f} to below 10⁻¹⁰. Coefficients match an independent least-squares calculation.</td></tr><tr><td>Does it interpolate?</td><td>Five held-out intermediate synthetic inputs agree within 10⁻⁶ m. Reversed examples reverse the fitted slope.</td></tr><tr><td>Do fresh tests change the model?</td><td>No. Parameters and training examples stay fixed; evaluation records survive switching modes.</td></tr><tr><td>Does the interface work?</td><td>Native slider and button signals, supplied XR trackers, target locking, interrupted captures and lesson switching are exercised in Godot.</td></tr><tr><td>Is it still one object?</td><td>The sphere's instance identity remains the same across POSE, HEIGHT, prediction and reset.</td></tr><tr><td>Is the museum affected?</td><td>Actual hall and standing-floor checks pass. The earlier pose and dance tests still pass.</td></tr></tbody></table>
    <p>Human demonstrations, controller ergonomics and headset performance remain to be tried. The surrounding hall retains older audio UID, computer-vision startup and portal diagnostics; the <a href="museum-diagnostics.json">capture log summary</a> preserves them. This report does not claim a clean whole-project log or a completed Machine Learning book sequence.</p>
    <h2>A compact lesson instruction</h2><p class="card">Carry the sphere. Pair mean head-relative hand height with chosen sphere height. Fit a line. Test fresh intermediate inputs without training. Reverse the pairs. Keep raw error visible. Ask which pose differences the single feature erases.</p>
    <h2>Code and evidence</h2><p><a href="notes.md">Full interaction and implementation notes</a> · <a href="height_learner.gd">Complete regression model</a> · <a href="height_learning.gd">Height interaction</a> · <a href="pose_learning_station.gd">Shared station</a></p><p><a href="tests.json">Height tests</a> · <a href="museum-tests.json">Museum tests</a> · <a href="pose-tests.json">Pose tests</a> · <a href="dance-tests.json">Dance tests</a> · <a href="source-register.json">Source hashes</a></p><details><summary>Read the complete small regression model</summary><pre><code>{code}</code></pre></details><p><a href="../2026-10-11-teach-a-sphere/index.html">Previous encounter: teach the sphere three poses</a></p></main></body></html>'''
    (OUT / 'index.html').write_text(content, encoding='utf-8')
    paths = ['commons/artifacts/vogue_timeline/' + name for name in ['height_learner.gd', 'height_learning.gd', 'pose_learning_station.gd', 'HEIGHT.md', 'LEARNING.md']]
    paths += ['tools/probes/height_learning_test.gd', 'tools/probes/height_learning_museum.gd', 'tools/test_height_learning.py', 'tools/publish_height_learning.py']
    (OUT / 'source-register.json').write_text(json.dumps({p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in paths}, indent=2), encoding='utf-8')
    print(f'Published {count} + {spatial} + {previous} passing checks: {OUT}')

if __name__ == '__main__': main()
